import {
  forwardRef,
  useState,
  Children,
  cloneElement,
  isValidElement,
  ReactElement,
  useRef,
  useEffect,
} from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { ChevronDown } from "@exp-textura/icons";

import {
  AIToolProps,
  AIToolContentProps,
  AIToolHeaderProps,
  AIToolLabelProps,
  AIToolIndicatorProps,
} from "./ai-tool.types";
import { AIToolClasses, StyledAITool } from "./ai-tool.styles";

export const AIToolHeader = forwardRef<HTMLButtonElement, AIToolHeaderProps>(
  ({ className, children, onClick, expanded, ...props }, ref) => {
    return (
      <button
        ref={ref}
        aria-expanded={expanded}
        className={clsx(AIToolClasses.header, className)}
        type="button"
        onClick={onClick}
        {...props}
      >
        {children}
      </button>
    );
  },
);
AIToolHeader.displayName = "AI.ToolHeader";

export const AIToolLabel = forwardRef<HTMLSpanElement, AIToolLabelProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <span ref={ref} className={clsx(AIToolClasses.headerContent, className)} {...props}>
        {children}
      </span>
    );
  },
);
AIToolLabel.displayName = "AI.ToolLabel";

export const AIToolIndicator = forwardRef<HTMLSpanElement, AIToolIndicatorProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <span ref={ref} className={clsx(AIToolClasses.icon, className)} {...props}>
        {children || <ChevronDown />}
      </span>
    );
  },
);
AIToolIndicator.displayName = "AI.ToolIndicator";

export const AIToolContent = forwardRef<HTMLDivElement, AIToolContentProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(AIToolClasses.content, className)} {...props}>
        {children}
      </div>
    );
  },
);
AIToolContent.displayName = "AI.ToolContent";

export const AITool = forwardRef(
  (
    {
      className,
      expanded: expandedProp,
      onExpandedChange,
      children,
      variant = "default",
      ...props
    }: AIToolProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(AIToolClasses.root, className);

    const [internalExpanded, setInternalExpanded] = useState(props.defaultExpanded ?? false);
    const isControlled = expandedProp !== undefined;
    const isExpanded = isControlled ? expandedProp : internalExpanded;
    const contentRef = useRef<HTMLDivElement>(null);
    const innerRef = useRef<HTMLDivElement>(null);

    const handleToggle = () => {
      const newState = !isExpanded;
      if (!isControlled) {
        setInternalExpanded(newState);
      }
      onExpandedChange?.(newState);
    };

    useEffect(() => {
      const container = contentRef.current;
      const inner = innerRef.current;
      if (!container || !inner) return;

      // Logic to sync max-height
      const syncHeight = () => {
        if (isExpanded) {
          container.style.maxHeight = `${inner.scrollHeight}px`;
        } else {
          container.style.maxHeight = "0px";
        }
      };

      // Initial sync
      syncHeight();

      // Observe the INNER content size
      const observer = new ResizeObserver(() => {
        if (isExpanded) {
          container.style.maxHeight = `${inner.scrollHeight}px`;
        }
      });

      observer.observe(inner);

      return () => {
        observer.disconnect();
      };
    }, [isExpanded]);

    const renderChildren = () => {
      let header: ReactElement | null = null;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const content: any[] = [];

      Children.forEach(children, (child) => {
        if (!isValidElement(child)) {
          content.push(child);
          return;
        }

        // Check if child is AIToolHeader
        if (
          (child.type as { displayName?: string }).displayName === "AI.ToolHeader" ||
          child.type === AIToolHeader
        ) {
          header = child as ReactElement;
        } else {
          content.push(child);
        }
      });

      const headerElement = header
        ? cloneElement(header, {
            onClick: (e: React.MouseEvent) => {
              handleToggle();
              header?.props.onClick?.(e);
            },
            expanded: isExpanded,
          })
        : null;

      if (!headerElement) {
        return <>{content}</>;
      }

      return (
        <>
          {headerElement}
          <div
            ref={contentRef}
            aria-hidden={!isExpanded}
            className={AIToolClasses.body}
            data-expanded={isExpanded}
          >
            <div ref={innerRef}>{content}</div>
          </div>
        </>
      );
    };

    return (
      <StyledAITool
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        data-expanded={isExpanded}
        variant={variant}
        {...props}
      >
        {renderChildren()}
      </StyledAITool>
    );
  },
);
AITool.displayName = "AI.Tool";
